<?php
namespace Engenharia\Models;
class Instruments_model extends EngenhariaBaseModel { protected $table = 'eng_instruments'; public function __construct(){ parent::__construct($this->table); } public function get_details(array $options=array()){ $builder=$this->db->table($this->db->prefixTable($this->table))->where('deleted',0); foreach(array('id','is_active') as $field){if(array_key_exists($field,$options)&&$options[$field]!==null&&$options[$field]!=='')$builder->where($field,$options[$field]);} if(!empty($options['limit']))$builder->limit((int)$options['limit']); if(!empty($options['offset']))$builder->offset((int)$options['offset']); return $builder->orderBy('name','ASC')->get(); } public function active(){return $this->db->table($this->db->prefixTable($this->table))->where('deleted',0)->where('is_active',1)->orderBy('name','ASC')->get();} public function saveRecord(array $data,int $id=0):int{$t=$this->db->prefixTable($this->table);$data['updated_at']=date('Y-m-d H:i:s');if($id){$this->db->table($t)->where('id',$id)->update($data);return$id;}$data+=array('deleted'=>0,'created_at'=>date('Y-m-d H:i:s'));$this->db->table($t)->insert($data);return(int)$this->db->insertID();} public function isExpired($row):bool{return !empty($row->calibration_valid_until)&&strtotime($row->calibration_valid_until)<strtotime(date('Y-m-d'));} }
